const rows = $input.all().map(item => item.json);
const today = new Date().toISOString().slice(0, 10);
const cooldownDays = 7;
const groceryCategories = new Set(['produce','dairy','pantry','snacks','household','personal_care','beverages','bakery']);
const toDate = (v) => {
  if (!v) return null;
  const d = new Date(String(v).slice(0, 10) + 'T00:00:00Z');
  return Number.isNaN(d.getTime()) ? null : d;
};
const age = (v) => {
  const d = toDate(v), t = toDate(today);
  return d && t ? Math.floor((t.getTime() - d.getTime()) / 86400000) : null;
};
const bool = (v) => ['true','1','yes','y','opted_in','consented'].includes(String(v ?? '').trim().toLowerCase());
const num = (v, fallback = 0) => Number.isFinite(Number(v)) ? Number(v) : fallback;
const decisions = [];
for (const c of rows) {
  const id = String(c.customer_id ?? '').trim();
  const email = String(c.email ?? '').trim();
  const consent = bool(c.marketing_consent);
  const orders = Math.max(0, Math.trunc(num(c.order_count)));
  const spend = num(c.total_spend_inr);
  const category = String(c.preferred_category || 'pantry').trim().toLowerCase();
  const recency = age(c.last_order_date);
  const signupAge = age(c.signup_date);
  const firstOrderAge = age(c.first_order_date);
  const lastCampaignAge = age(c.last_campaign_date);
  let row = {
    customer_id: id, first_name: String(c.first_name || 'there'), email,
    segment: 'Suppressed', campaign_type: 'None', recommended_offer: 'No offer',
    decision_reason: 'Not eligible', eligible: false, suppression_reason: '',
    days_since_last_order: recency ?? '', order_count: orders,
    total_spend_inr: spend, preferred_category: category, original_customer: c,
  };
  if (!id) row.suppression_reason = 'missing_customer_id';
  else if (!email || !email.includes('@')) row.suppression_reason = 'missing_or_invalid_email';
  else if (!consent) row.suppression_reason = 'no_marketing_consent';
  else if (c.last_campaign_date && lastCampaignAge !== null && lastCampaignAge >= 0 && lastCampaignAge < cooldownDays) row.suppression_reason = 'campaign_cooldown';
  if (row.suppression_reason) {
    row.decision_reason = `Suppressed: ${row.suppression_reason}`;
    decisions.push(row);
    continue;
  }

  const replenishDays = Math.max(7, Math.trunc(num(c.typical_replenishment_days, 21)));
  if (orders === 0) {
    row.segment = signupAge !== null && signupAge <= 7 ? 'New Signup' : 'Dormant Signup';
    row.campaign_type = 'First Order Activation';
    row.recommended_offer = '5% off the first order, capped at ₹100';
    row.decision_reason = 'Signed up but has not placed a first order.';
  } else if (orders === 1 && recency !== null && recency <= 14) {
    row.segment = 'First-Order Customer';
    row.campaign_type = 'Post-Purchase Reorder';
    row.recommended_offer = 'No discount by default; recommend relevant add-ons';
    row.decision_reason = 'First order is recent; support satisfaction and the next order.';
  } else if (orders === 1) {
    row.segment = 'One-Time Buyer';
    row.campaign_type = 'First-to-Second Order';
    row.recommended_offer = '5% off the next order, capped at ₹100';
    row.decision_reason = 'Customer has placed one order but has not returned recently.';
  } else if (recency !== null && recency >= 45) {
    row.segment = spend >= 8000 ? 'High-Value Win-Back' : 'Dormant Repeat Customer';
    row.campaign_type = 'Win-Back';
    row.recommended_offer = '10% off an order above ₹799, capped at ₹150';
    row.decision_reason = `Repeat customer inactive for ${recency} days.`;
  } else if (spend >= 6000 && recency !== null && recency >= 21) {
    row.segment = 'High-Value At-Risk';
    row.campaign_type = 'VIP Re-engagement';
    row.recommended_offer = 'Personalized basket first; incentive only if approved';
    row.decision_reason = `High-spend customer shows an early inactivity signal (${recency} days).`;
  } else if (groceryCategories.has(category) && recency !== null && recency >= replenishDays - 3 && recency <= replenishDays + 10) {
    row.segment = 'Replenishment Due';
    row.campaign_type = 'Replenishment Reminder';
    row.recommended_offer = 'No discount by default; show relevant replenishment items';
    row.decision_reason = `Last order was ${recency} days ago, near the ${replenishDays}-day replenishment cadence.`;
  } else if (recency !== null && recency <= 14) {
    row.segment = 'Active Repeat Customer';
    row.campaign_type = 'Cross-Sell & Habit';
    row.recommended_offer = 'No discount by default; recommend complementary essentials';
    row.decision_reason = 'Recent repeat customer; encourage useful discovery and habit formation.';
  } else {
    row.segment = 'Active Customer Nurture';
    row.campaign_type = 'Relevant Category Nurture';
    row.recommended_offer = 'No discount by default; use category-relevant recommendations';
    row.decision_reason = 'Customer does not match a higher-priority lifecycle trigger.';
  }
  row.eligible = true;
  decisions.push(row);
}
const eligible = decisions.filter(r => r.eligible);
const groups = new Map();
for (const c of eligible) {
  if (!groups.has(c.campaign_type)) groups.set(c.campaign_type, []);
  groups.get(c.campaign_type).push(c);
}
return Array.from(groups.entries()).map(([campaign_type, customers]) => ({json: {
  campaign_type,
  segment_labels: [...new Set(customers.map(c => c.segment))],
  customer_count: customers.length,
  offer_examples: [...new Set(customers.map(c => c.recommended_offer))].slice(0, 4),
  customers,
  evaluation_date: today,
}}));

const groups = $('Segment & Group Customers').all().map(item => item.json);
const aiResponses = $input.all().map(item => item.json);
const fallback = {
  'First Order Activation': {subject_template:'Your grocery essentials are waiting, {first_name}', body_template:'Hi {first_name}, discover everyday essentials picked for your {preferred_category} preferences. Use {offer} on your first order, subject to the offer terms.', cta:'Explore your first basket', rationale:'Reduce signup-to-first-order friction.'},
  'Post-Purchase Reorder': {subject_template:'How did your first basket go, {first_name}?', body_template:'Hi {first_name}, we hope your first order went smoothly. Explore useful add-ons in {preferred_category}. {offer}', cta:'Build your next basket', rationale:'Make the second order easier.'},
  'First-to-Second Order': {subject_template:'Ready for your next basket, {first_name}?', body_template:'Hi {first_name}, revisit {preferred_category} favourites and use {offer} if it fits your basket.', cta:'Shop your favourites', rationale:'Address the one-time-buyer gap.'},
  'Win-Back': {subject_template:'A fresh grocery run, on your terms, {first_name}', body_template:'Hi {first_name}, it has been a while since your last basket. See what is new in {preferred_category}. Your eligible return offer: {offer}.', cta:'Come back to your basket', rationale:'Encourage a lapsed repeat customer to return.'},
  'VIP Re-engagement': {subject_template:'A more relevant basket for you, {first_name}', body_template:'Hi {first_name}, explore a curated basket around your {preferred_category} preferences. {offer}', cta:'See your recommendations', rationale:'Prioritize relevance before discounting.'},
  'Replenishment Reminder': {subject_template:'Running low on {preferred_category}, {first_name}?', body_template:'Hi {first_name}, it may be time to restock your {preferred_category} essentials. Check your favourites. {offer}', cta:'Restock essentials', rationale:'Prompt likely replenishment using observed cadence.'},
  'Cross-Sell & Habit': {subject_template:'Ideas for your next grocery basket, {first_name}', body_template:'Hi {first_name}, discover complementary picks alongside your usual {preferred_category} favourites. {offer}', cta:'Explore recommendations', rationale:'Support useful discovery without defaulting to discounts.'},
  'Relevant Category Nurture': {subject_template:'A few fresh ideas for your basket, {first_name}', body_template:'Hi {first_name}, explore new picks in {preferred_category} and build a basket around what you need. {offer}', cta:'Browse your category', rationale:'Keep category recommendations relevant.'},
};
const today = new Date().toISOString().slice(0,10);
const fill = (s, c) => String(s || '').replaceAll('{first_name}', String(c.first_name || 'there')).replaceAll('{preferred_category}', String(c.preferred_category || 'grocery').replaceAll('_',' ')).replaceAll('{offer}', String(c.recommended_offer || ''));
const output = [];
for (let i = 0; i < groups.length; i++) {
  const group = groups[i];
  const response = aiResponses[i] || {};
  let ai = null;
  try {
    const content = response.choices?.[0]?.message?.content;
    const parsed = typeof content === 'string' ? JSON.parse(content) : null;
    if (parsed && ['subject_template','body_template','cta','rationale'].every(k => typeof parsed[k] === 'string' && parsed[k].trim())) {
      const all = parsed.subject_template + parsed.body_template;
      if (all.includes('{first_name}') && all.includes('{preferred_category}') && all.includes('{offer}')) ai = parsed;
    }
  } catch (e) { ai = null; }
  const template = ai || fallback[group.campaign_type] || fallback['Relevant Category Nurture'];
  for (const c of group.customers) {
    output.push({json: {
      campaign_id: `DRAFT-${c.customer_id}-${today.replaceAll('-','')}`,
      generated_at: today,
      customer_id: c.customer_id,
      first_name: c.first_name,
      email: c.email,
      segment: c.segment,
      campaign_type: c.campaign_type,
      decision_reason: c.decision_reason,
      recommended_offer: c.recommended_offer,
      subject: fill(template.subject_template, c),
      message_body: fill(template.body_template, c),
      cta: template.cta,
      copy_rationale: template.rationale,
      preferred_category: c.preferred_category,
      days_since_last_order: c.days_since_last_order,
      order_count: c.order_count,
      total_spend_inr: c.total_spend_inr,
      channel: 'email_draft',
      status: 'DRAFT_REQUIRES_REVIEW',
      send_approved: 'NO',
      draft_source: ai ? 'OpenAI API' : 'Fallback template',
    }});
  }
}
return output;
